      <div className="grid grid-cols-1 gap-8 lg:grid-cols-2 lg:gap-12 max-w-7xl mx-auto">
        {projects.map((project, index) => (
          <motion.div
            key={project.title}
            initial={{ opacity: 0, x: index % 2 === 0 ? -50 : 50 }}
